<script setup lang="ts">
import type {ChartSettings} from '../state/project';
defineProps<{settings:ChartSettings}>();
const emit=defineEmits<{change:[value:Partial<ChartSettings>]} >();
</script>
<template><section class="property-section chart-style-editor"><label>标题与图例</label><div class="style-line"><span>主标题</span><input type="number" min="10" max="36" :value="settings.titleFontSize" @input="emit('change',{titleFontSize:Number(($event.target as HTMLInputElement).value)})"><input type="color" :value="settings.titleColor||'#172033'" @input="emit('change',{titleColor:($event.target as HTMLInputElement).value})"><select :value="settings.titleAlign" @change="emit('change',{titleAlign:($event.target as HTMLSelectElement).value as 'start'|'center'|'end'})"><option value="start">左对齐</option><option value="center">居中</option><option value="end">右对齐</option></select></div><div class="style-line"><span>副标题</span><input type="number" min="9" max="28" :value="settings.subtitleFontSize" @input="emit('change',{subtitleFontSize:Number(($event.target as HTMLInputElement).value)})"><input type="color" :value="settings.subtitleColor||'#687386'" @input="emit('change',{subtitleColor:($event.target as HTMLInputElement).value})"></div><div class="style-line"><span>图例</span><input type="number" min="8" max="24" :value="settings.legendFontSize" @input="emit('change',{legendFontSize:Number(($event.target as HTMLInputElement).value)})"><select :value="settings.legendPointStyle" @change="emit('change',{legendPointStyle:($event.target as HTMLSelectElement).value as 'circle'|'rect'|'line'})"><option value="circle">圆点</option><option value="rect">方块</option><option value="line">线段</option></select><label class="mini-check">逆序<input type="checkbox" :checked="settings.legendReverse" @change="emit('change',{legendReverse:($event.target as HTMLInputElement).checked})"></label></div><template v-if="settings.showDataLabels"><label>数据标签</label><div class="style-line"><span>标签</span><input type="number" min="8" max="24" :value="settings.dataLabelFontSize" @input="emit('change',{dataLabelFontSize:Number(($event.target as HTMLInputElement).value)})"><input type="color" :value="settings.dataLabelColor||'#172033'" @input="emit('change',{dataLabelColor:($event.target as HTMLInputElement).value})"><input type="color" :value="settings.dataLabelBackground||'#ffffff'" title="背景" @input="emit('change',{dataLabelBackground:($event.target as HTMLInputElement).value})"><input type="color" :value="settings.dataLabelBorderColor||'#e8eaf0'" title="边框" @input="emit('change',{dataLabelBorderColor:($event.target as HTMLInputElement).value})"></div><div class="style-line"><span>位置</span><label>旋转<input type="number" min="-90" max="90" :value="settings.dataLabelRotation" @input="emit('change',{dataLabelRotation:Number(($event.target as HTMLInputElement).value)})"></label><label>偏移<input type="number" min="-30" max="30" :value="settings.dataLabelOffset" @input="emit('change',{dataLabelOffset:Number(($event.target as HTMLInputElement).value)})"></label></div></template><label>绘图区</label><div class="style-line"><span>边距</span><input type="number" min="0" max="60" :value="settings.plotPadding" @input="emit('change',{plotPadding:Number(($event.target as HTMLInputElement).value)})"><span>边框</span><input type="number" min="0" max="6" :value="settings.plotBorderWidth" @input="emit('change',{plotBorderWidth:Number(($event.target as HTMLInputElement).value)})"><input type="color" :value="settings.plotBorderColor||'#e8eaf0'" @input="emit('change',{plotBorderColor:($event.target as HTMLInputElement).value})"></div></section></template>
